css:
.sentinelsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e9eef4;
    background:
        linear-gradient(135deg, rgba(10, 17, 26, 0.96) 0%, rgba(17, 26, 38, 0.96) 100%),
        repeating-linear-gradient(45deg, rgba(255,255,255,0.015) 0px, rgba(255,255,255,0.015) 2px, transparent 2px, transparent 9px);
    background-color: #0c141f;
    border-radius: 14px;
    border: 1px solid #233140;
}

.sentinelsim-container * {
    box-sizing: border-box;
}

.sentinelsim-header {
    position: relative;
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(120deg, #14202e 0%, #1b2c3e 60%, #243a2c 100%);
    color: #f3f7fb;
    border-radius: 12px;
    margin-bottom: 20px;
    border: 1px solid #2a3e52;
    border-left: 6px solid #f0a830;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
}

.sentinelsim-header h1 {
    margin: 10px 0 12px;
    font-size: 2.25rem;
    font-weight: 800;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    color: #ffffff;
}

.sentinelsim-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #f0a830;
    background: rgba(240, 168, 48, 0.12);
    border: 1px solid rgba(240, 168, 48, 0.35);
    padding: 5px 14px;
    border-radius: 4px;
}

.sentinelsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #b7c6d6;
}

.sentinelsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.95rem;
    font-weight: 600;
    color: #8ea3b9;
    margin-bottom: 18px;
    padding: 6px 4px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.sentinelsim-period-counter #currentDay,
.sentinelsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #38c6d9;
}

.sentinelsim-round-name {
    background: rgba(56, 198, 217, 0.14);
    color: #38c6d9;
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 0.8rem;
    font-weight: 700;
    margin-left: 4px;
    letter-spacing: 0.4px;
}

.sentinelsim-clock {
    margin-left: auto;
    font-size: 0.8rem;
    font-weight: 700;
    color: #ff8a5b;
    background: rgba(255, 138, 91, 0.12);
    border: 1px solid rgba(255, 138, 91, 0.35);
    padding: 4px 12px;
    border-radius: 4px;
}

.sentinelsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.sentinelsim-status-card {
    background: linear-gradient(165deg, #16222f 0%, #101a25 100%);
    border-radius: 8px;
    padding: 16px 16px 14px;
    border: 1px solid #263749;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.4);
    border-top: 4px solid #3a5a78;
}

.sentinelsim-card-adopt { border-top-color: #38c6d9; }
.sentinelsim-card-trust { border-top-color: #6fcf97; }
.sentinelsim-card-popia { border-top-color: #b08bff; }
.sentinelsim-card-fin { border-top-color: #f0a830; }

.sentinelsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #87a0ba;
}

.sentinelsim-value {
    font-size: 2.55rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f3f7fb;
    font-variant-numeric: tabular-nums;
}

.sentinelsim-card-adopt .sentinelsim-value { color: #38c6d9; }
.sentinelsim-card-trust .sentinelsim-value { color: #6fcf97; }
.sentinelsim-card-popia .sentinelsim-value { color: #b08bff; }
.sentinelsim-card-fin .sentinelsim-value { color: #f0a830; }

.sentinelsim-sublabel {
    font-size: 0.75rem;
    color: #7990a8;
    line-height: 1.35;
}

.sentinelsim-fin-negative .sentinelsim-value { color: #ff6b5e; }
.sentinelsim-fin-negative { border-top-color: #ff6b5e; }
.sentinelsim-fin-positive .sentinelsim-value { color: #6fcf97; }
.sentinelsim-fin-positive { border-top-color: #6fcf97; }

.sentinelsim-adopt-low .sentinelsim-value { color: #ff6b5e; }
.sentinelsim-adopt-low { border-top-color: #ff6b5e; }
.sentinelsim-adopt-high .sentinelsim-value { color: #6fcf97; }

.sentinelsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0e1925;
    border: 1px solid #263749;
    border-left: 4px solid #f0a830;
    color: #cfdcea;
    padding: 10px 18px;
    border-radius: 6px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
}

.sentinelsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f0a830;
}

.sentinelsim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(165deg, #16222f 0%, #101a25 100%);
    border-left: 5px solid #38c6d9;
    border-radius: 8px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

.sentinelsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.sentinelsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #f3f7fb;
    margin-bottom: 6px;
}

.sentinelsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #bdcdde;
}

.sentinelsim-briefing-text strong { color: #38c6d9; }
.sentinelsim-briefing-text em { color: #f0a830; font-style: italic; }

.sentinelsim-controls {
    background: linear-gradient(165deg, #121d29 0%, #0d1722 100%);
    border-radius: 10px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #263749;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

.sentinelsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.1rem;
    font-weight: 800;
    color: #f3f7fb;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    border-bottom: 2px solid #263749;
    padding-bottom: 8px;
}

.sentinelsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #cadaeb;
    margin: 16px 0 6px;
}

.sentinelsim-container select,
.sentinelsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2f485f;
    border-radius: 6px;
    font-size: 0.92rem;
    background-color: #0f1d2b;
    color: #eaf2fb;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.sentinelsim-container select:focus,
.sentinelsim-container input[type="number"]:focus {
    outline: none;
    border-color: #38c6d9;
    box-shadow: 0 0 0 3px rgba(56, 198, 217, 0.20);
}

.sentinelsim-container select option {
    background-color: #0f1d2b;
    color: #eaf2fb;
}

.sentinelsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #38c6d9;
}

.sentinelsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #8ea3b9;
    margin-top: 4px;
}

.sentinelsim-range-readout span:nth-child(2) {
    color: #38c6d9;
    font-weight: 800;
}

.sentinelsim-hint {
    font-size: 0.8rem;
    color: #7990a8;
    margin-top: 6px;
    line-height: 1.4;
    border-left: 2px solid #2f485f;
    padding-left: 10px;
}

.sentinelsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.6px;
}

.sentinelsim-container .btn-primary {
    background: linear-gradient(135deg, #c47d12 0%, #f0a830 100%);
    border: none;
    color: #1a1206;
    padding: 12px 28px;
    border-radius: 6px;
    box-shadow: 0 8px 20px rgba(240, 168, 48, 0.30);
}

.sentinelsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.sentinelsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #2f485f;
    color: #8ea3b9;
    background: transparent;
}

.sentinelsim-coach {
    background: linear-gradient(165deg, #0e1925 0%, #161f17 100%);
    color: #d6e3f0;
    border: 1px solid #2a3e2c;
    border-left: 5px solid #6fcf97;
    border-radius: 10px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

.sentinelsim-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #6fcf97;
    margin-bottom: 8px;
}

.sentinelsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.sentinelsim-coach-body strong { color: #6fcf97; }
.sentinelsim-coach-body em { color: #f0a830; font-style: italic; }

.sentinelsim-history,
.sentinelsim-chart {
    background: linear-gradient(165deg, #121d29 0%, #0d1722 100%);
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #263749;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35);
}

.sentinelsim-history h3,
.sentinelsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.06rem;
    font-weight: 800;
    color: #f3f7fb;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.sentinelsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cadaeb;
}

.sentinelsim-container table#usfHistoryTable th {
    background: #0f1d2b;
    color: #38c6d9;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.71rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #2f485f;
}

.sentinelsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #1d2b3a;
    color: #bdcdde;
}

.sentinelsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #0e1925;
}

.sentinelsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .sentinelsim-container {
        padding: 14px;
    }
    .sentinelsim-header h1 {
        font-size: 1.6rem;
    }
    .sentinelsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .sentinelsim-value {
        font-size: 2rem;
    }
    .sentinelsim-clock {
        margin-left: 0;
    }
    .sentinelsim-period-counter {
        font-size: 0.85rem;
    }
    .sentinelsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .sentinelsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (sentinelsim) ---- */
.sentinelsim-completion { padding: 8px 4px 4px; }
.sentinelsim-cm-head { text-align: center; margin-bottom: 16px; }
.sentinelsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #3f6fa0; }
.sentinelsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #82a2c2; }
.sentinelsim-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #1f2a38; }
.sentinelsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.sentinelsim-cm-yes { background: rgba(63,111,160,0.16); color: #3f6fa0; border: 1px solid rgba(63,111,160,0.5); }
.sentinelsim-cm-no { background: rgba(180,70,55,0.12); color: #a5412c; border: 1px solid rgba(180,70,55,0.45); }
.sentinelsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.sentinelsim-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(63,111,160,0.08); border: 1px solid rgba(63,111,160,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.sentinelsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #3f6fa0; }
.sentinelsim-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #656b7c; text-transform: uppercase; letter-spacing: 0.03em; }
.sentinelsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #1f2a38; }
.sentinelsim-cm-insights { margin: 0; padding-left: 20px; }
.sentinelsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #363c4b; }

