(function() {
    'use strict';

    class SentinelAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Systems & Ethics`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Sentinel Logistics, ZAR).
            this.PROGRAMME_COST = 180;       // ZAR 180M WOMS programme
            this.EFFICIENCY_TARGET = 95;     // ZAR 95M promised annual efficiency gain
            this.DOWNSIDE = -40;             // ZAR ~40M loss in the non-adoption scenario
            this.START_ADOPTION = 38;        // 38% early frontline adoption (willing)
            this.BUDGET_CAP = 25;            // ZAR 25M envelope for change + safeguard spend
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    adoption: 38,            // % frontline using WOMS as intended
                    trust: 30,               // worker & union trust (rebuilds slowly)
                    popia: 20,               // POPIA compliance posture
                    fin: 0,                  // ZAR M net financial outcome vs status quo
                    budgetUsed: 0,           // ZAR M change + safeguard spend committed
                    analyticsOff: false,     // people-analytics module switched off entirely
                    surveillanceLed: false,  // individual data driving performance/headcount
                    symbolicSafeguard: false,// charter with no teeth
                    adoptionHistory: [38],
                    trustHistory: [30],
                    popiaHistory: [20],
                    finHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately wrong-leaning mix —
                // a blind click-through must not auto-win (it triggers the classic failures).
                state.decisions = {
                    frame: `neutral`,
                    risk: `bugs`,
                    listen: 40,
                    purpose: `hr`,
                    access: `open`,
                    popiaStance: `skip`,
                    safety: `ungoverned`,
                    sequence: `bigbang`,
                    consult: `none`,
                    invest: 0,
                    target: 70,
                    safeguard: `charter`,
                    teeth: `symbolic`,
                    safeInvest: 0,
                    defence: `board`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const fr = document.getElementById(`frameInput`);
                const rk = document.getElementById(`riskInput`);
                const ls = document.getElementById(`listenInput`);
                if (fr) decisions.frame = fr.value;
                if (rk) decisions.risk = rk.value;
                if (ls) decisions.listen = parseInt(ls.value, 10);
                if (!Number.isFinite(decisions.listen) || decisions.listen < 0 || decisions.listen > 100) {
                    warn(`warn_listen_range`); return false;
                }
            } else if (round === 2) {
                const pu = document.getElementById(`purposeInput`);
                const ac = document.getElementById(`accessInput`);
                const po = document.getElementById(`popiaInput`);
                const sa = document.getElementById(`safetyInput`);
                if (pu) decisions.purpose = pu.value;
                if (ac) decisions.access = ac.value;
                if (po) decisions.popiaStance = po.value;
                if (sa) decisions.safety = sa.value;
                if (!decisions.purpose || !decisions.access || !decisions.popiaStance || !decisions.safety) {
                    warn(`warn_incomplete`); return false;
                }
            } else if (round === 3) {
                const sq = document.getElementById(`sequenceInput`);
                const co = document.getElementById(`consultInput`);
                const iv = document.getElementById(`investInput`);
                const tg = document.getElementById(`targetInput`);
                if (sq) decisions.sequence = sq.value;
                if (co) decisions.consult = co.value;
                if (iv) decisions.invest = parseFloat(iv.value);
                if (tg) decisions.target = parseInt(tg.value, 10);
                if (!Number.isFinite(decisions.invest) || decisions.invest < 0) {
                    warn(`warn_invest_value`); return false;
                }
                if (!Number.isFinite(decisions.target) || decisions.target < 38 || decisions.target > 100) {
                    warn(`warn_target_range`); return false;
                }
            } else if (round === 4) {
                const sf = document.getElementById(`safeguardInput`);
                const te = document.getElementById(`teethInput`);
                const si = document.getElementById(`safeInvestInput`);
                const df = document.getElementById(`defenceInput`);
                const cv = document.getElementById(`convictionInput`);
                if (sf) decisions.safeguard = sf.value;
                if (te) decisions.teeth = te.value;
                if (si) decisions.safeInvest = parseFloat(si.value);
                if (df) decisions.defence = df.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.safeInvest) || decisions.safeInvest < 0) {
                    warn(`warn_safeinvest_value`); return false;
                }
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let adoptDelta = 0, trustDelta = 0, popiaDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Read the SOCIAL system, not just the technical one (Common Error 1).
                switch (d.frame) {
                    case `sociotechnical`: trustDelta += 10; adoptDelta += 4; popiaDelta += 4; coachKey = `coach_r1_socio`; break;
                    case `neutral`: trustDelta -= 6; adoptDelta -= 2; coachKey = `coach_r1_neutral`; break;
                    case `technical`: trustDelta -= 3; coachKey = `coach_r1_technical`; break;
                    case `cost`: trustDelta -= 8; adoptDelta -= 3; coachKey = `coach_r1_cost`; break;
                }

                // Name the real risk: the social subsystem rejecting the technical one.
                switch (d.risk) {
                    case `rejection`: trustDelta += 6; popiaDelta += 3; if (d.frame === `sociotechnical`) coachKey = `coach_r1_sharp`; break;
                    case `bugs`: trustDelta -= 3; break;
                    case `press`: trustDelta -= 2; break;
                    case `contained`: trustDelta -= 6; adoptDelta -= 2; coachKey = `coach_r1_contained`; break;
                }

                // Genuine listening builds the trust foundation for everything later.
                if (d.listen >= 60) { trustDelta += 6; adoptDelta += 3; }
                else if (d.listen <= 25) { trustDelta -= 5; coachKey = `coach_r1_notlistening`; }

                summaryKey = (d.frame === `sociotechnical` && d.risk === `rejection`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Set the data-use rules — purpose limitation is the trust hinge (Common Error 2).
                switch (d.purpose) {
                    case `coord`: trustDelta += 12; adoptDelta += 6; popiaDelta += 10; coachKey = `coach_r2_coord`; break;
                    case `perf`: trustDelta -= 2; popiaDelta += 2; coachKey = `coach_r2_perf`; break;
                    case `hr`: trustDelta -= 14; adoptDelta -= 8; popiaDelta -= 8; ds.surveillanceLed = true; coachKey = `coach_r2_hr`; break;
                }

                // Access & automated decisions.
                switch (d.access) {
                    case `aggregate`: trustDelta += 8; popiaDelta += 8; adoptDelta += 3; break;
                    case `managers`: trustDelta += 2; popiaDelta += 3; break;
                    case `open`: trustDelta -= 8; popiaDelta -= 6; if (!ds.surveillanceLed) ds.surveillanceLed = true; break;
                }

                // POPIA formal footing (Common Error 5b / facilitator: "Where's your DPIA?").
                switch (d.popiaStance) {
                    case `full`: popiaDelta += 16; trustDelta += 4; coachKey = (d.purpose === `coord`) ? `coach_r2_bydesign` : coachKey; break;
                    case `partial`: popiaDelta += 4; break;
                    case `skip`: popiaDelta -= 12; trustDelta -= 3; coachKey = `coach_r2_nodpia`; break;
                }

                // Dual-use governance: switching analytics OFF forfeits the safety upside AND the efficiency case
                // (Common Error 5a). Governing it is the responsible middle.
                switch (d.safety) {
                    case `govern`: trustDelta += 6; popiaDelta += 4; adoptDelta += 2; break;
                    case `off`: ds.analyticsOff = true; trustDelta += 2; adoptDelta -= 2; coachKey = `coach_r2_off`; break;
                    case `ungoverned`: trustDelta -= 6; popiaDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r2_ungoverned` : coachKey; break;
                }

                summaryKey = (d.purpose === `coord` && d.popiaStance === `full` && d.safety === `govern`) ? `sum_r2_good` :
                             (d.purpose === `hr` ? `sum_r2_surveillance` : `sum_r2_weak`);
            } else if (round === 3) {
                // Choose the change & adoption approach — adoption is co-produced (Common Error 3).
                switch (d.sequence) {
                    case `phased`: trustDelta += 6; adoptDelta += 5; coachKey = `coach_r3_phased`; break;
                    case `fast`: adoptDelta += 1; break;
                    case `bigbang`: trustDelta -= 5; adoptDelta -= 4; coachKey = `coach_r3_bigbang`; break;
                }

                switch (d.consult) {
                    case `codesign`: trustDelta += 12; adoptDelta += 8; popiaDelta += 3; coachKey = (d.sequence === `phased`) ? `coach_r3_codesign` : coachKey; break;
                    case `inform`: trustDelta += 2; adoptDelta += 2; break;
                    case `none`: trustDelta -= 12; adoptDelta -= 6; coachKey = `coach_r3_noconsult`; break;
                }

                // Training / transparency / adoption support investment (metered against the budget).
                spend += d.invest;
                if (d.invest >= 9) { adoptDelta += 8; trustDelta += 4; }
                else if (d.invest >= 4) { adoptDelta += 4; trustDelta += 1; }
                else { adoptDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r3_noinvest` : coachKey; }

                // Target realism: a target far above the supportable ceiling reads as wishful and costs trust.
                const supportable = 38
                    + (d.consult === `codesign` ? 28 : d.consult === `inform` ? 10 : -4)
                    + (d.invest >= 9 ? 18 : d.invest >= 4 ? 9 : 0)
                    + (ds.surveillanceLed ? -20 : 8);
                if (d.target > supportable + 12) { trustDelta -= 6; coachKey = `coach_r3_overpromise`; }
                else if (d.target <= supportable) { trustDelta += 3; }

                summaryKey = (d.consult === `codesign` && d.invest >= 4 && d.sequence !== `bigbang`) ? `sum_r3_good` :
                             (d.consult === `none` ? `sum_r3_imposed` : `sum_r3_weak`);
            } else if (round === 4) {
                // Install a binding ethics safeguard & defend (Common Error 4).
                switch (d.safeguard) {
                    case `oversight`: popiaDelta += 10; trustDelta += 12; coachKey = `coach_r4_oversight`; break;
                    case `hitl`: popiaDelta += 10; trustDelta += 8; coachKey = `coach_r4_hitl`; break;
                    case `charter`: popiaDelta += 2; trustDelta += 2; break;
                    case `none`: popiaDelta -= 8; trustDelta -= 6; coachKey = `coach_r4_nosafeguard`; break;
                }

                // Teeth decide whether the safeguard is real or PR.
                switch (d.teeth) {
                    case `binding`: trustDelta += 12; popiaDelta += 8; adoptDelta += 5; break;
                    case `partial`: trustDelta += 3; popiaDelta += 2; break;
                    case `symbolic`: trustDelta -= 8; popiaDelta -= 4; ds.symbolicSafeguard = true; coachKey = `coach_r4_symbolic`; break;
                }
                // A charter without teeth is the canonical "lovely charter, no human-in-the-loop" failure.
                if (d.safeguard === `charter` && d.teeth === `symbolic`) { ds.symbolicSafeguard = true; coachKey = `coach_r4_charter`; }

                // Fund it (metered against the budget).
                spend += d.safeInvest;
                if (d.safeInvest >= 6) { trustDelta += 5; popiaDelta += 4; }
                else if (d.safeInvest >= 3) { trustDelta += 2; }
                else if (d.teeth === `binding`) { trustDelta -= 4; coachKey = `coach_r4_underfunded`; }

                // The defence — reconcile efficiency, POPIA, union relations and trust.
                switch (d.defence) {
                    case `integrated`: trustDelta += 8; popiaDelta += 4; if (d.teeth === `binding`) coachKey = `coach_r4_defended`; break;
                    case `board`: trustDelta -= 4; coachKey = `coach_r4_boardonly`; break;
                    case `deflect`: trustDelta -= 10; popiaDelta -= 4; coachKey = `coach_r4_deflect`; break;
                }

                if (d.conviction >= 60) { trustDelta += 4; }
                else if (d.conviction <= 25) { trustDelta -= 4; }

                summaryKey = (d.safeguard !== `none` && d.safeguard !== `charter` && d.teeth === `binding` && d.defence === `integrated`) ? `sum_r4_good` :
                             (ds.symbolicSafeguard ? `sum_r4_symbolic` : `sum_r4_weak`);
            }

            // Apply trust first (it gates adoption). Trust rebuilds SLOWLY: positive gains are damped.
            const trustGain = trustDelta > 0 ? trustDelta * 0.7 : trustDelta;
            ds.trust = Math.max(0, Math.min(100, Math.round(ds.trust + trustGain)));
            ds.popia = Math.max(0, Math.min(100, Math.round(ds.popia + popiaDelta)));

            // Adoption responds dynamically: it is pulled toward a trust-driven ceiling, plus the round's
            // direct levers. Surveillance-led use and a symbolic safeguard cap the ceiling hard.
            let ceiling = 30 + ds.trust * 0.55;
            if (ds.surveillanceLed) ceiling -= 22;     // "treats the system as a threat, feeds it the minimum"
            if (ds.symbolicSafeguard) ceiling -= 10;
            if (ds.analyticsOff) ceiling -= 6;          // less to adopt, less reason to engage
            ceiling = Math.max(5, Math.min(98, ceiling));
            // Move ~45% of the way toward the ceiling each round, then add the direct lever delta.
            ds.adoption = ds.adoption + (ceiling - ds.adoption) * 0.45 + adoptDelta;
            ds.adoption = Math.max(0, Math.min(100, Math.round(ds.adoption)));

            // Net financial outcome: the ZAR 95M target is realised only in proportion to real adoption,
            // net of the change/safeguard spend; deep non-adoption tips into the ~ZAR 40M downside.
            const adoptFrac = ds.adoption / 100;
            let realisedGain;
            if (ds.adoption >= 55) {
                realisedGain = this.EFFICIENCY_TARGET * adoptFrac;            // up toward +R95M
            } else {
                // Below the adoption floor, gaming/dispute/reputational drag pulls toward the -R40M downside.
                const shortfall = (55 - ds.adoption) / 55;                    // 0..1
                realisedGain = this.EFFICIENCY_TARGET * adoptFrac - shortfall * 70;
            }
            if (ds.surveillanceLed && ds.adoption < 55) realisedGain -= 12;   // trust collapse compounds the loss
            ds.fin = Math.round(realisedGain - ds.budgetUsed - spend);

            // Meter the cumulative change + safeguard budget.
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round((ds.budgetUsed + spend) * 10) / 10);

            ds.adoptionHistory.push(ds.adoption);
            ds.trustHistory.push(ds.trust);
            ds.popiaHistory.push(ds.popia);
            ds.finHistory.push(ds.fin);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                adoption: ds.adoption,
                adoptDelta: Math.round(adoptDelta),
                trust: ds.trust,
                trustDelta: Math.round(trustDelta),
                popia: ds.popia,
                popiaDelta: Math.round(popiaDelta),
                fin: ds.fin,
                budgetUsed: ds.budgetUsed,
                surveillanceLed: ds.surveillanceLed,
                symbolicSafeguard: ds.symbolicSafeguard,
                analyticsOff: ds.analyticsOff,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // ZAR: single, unambiguous symbol "R" before the number (e.g. R95M, -R40M).
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(Math.round(v));
            return `${sign}R${abs}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
