        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.adoptionHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                sentinelChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.adoptionHistory },
                        { data: ds.trustHistory },
                        { data: ds.popiaHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const adoption = Math.round(ds.adoption);
            const trust = Math.round(ds.trust);
            const popia = Math.round(ds.popia);
            const fin = ds.fin;
            const finScore = Math.max(-25, Math.min(25, fin * 0.25));
            return Math.max(0, Math.min(100, Math.round(adoption * 0.30 + trust * 0.28 + popia * 0.26 + (finScore + 25) * 0.32)));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const adoption = Math.round(ds.adoption);
            const trust = Math.round(ds.trust);
            const popia = Math.round(ds.popia);
            const fin = ds.fin;

            // Composite: adoption, trust, POPIA, plus a financial bonus
            // (each ZAR M of net outcome worth ~0.25 pts, capped at ±25).
            const composite = this._composite(ds);

            const adopted = adoption >= 65;
            const trusted = trust >= 60;
            const compliant = popia >= 60;
            const profitable = fin >= 40;
            const exposed = ds.surveillanceLed && adoption < 55;
            const symbolic = ds.symbolicSafeguard;

            let performance = window.mySimulation.t(`grade_stalled`);
            if (adopted && trusted && compliant && profitable && composite >= 75) performance = window.mySimulation.t(`grade_responsible`);
            else if (trusted && compliant && adopted) performance = window.mySimulation.t(`grade_trust`);
            else if (exposed) performance = window.mySimulation.t(`grade_backlash`);
            else if (symbolic && trust < 50) performance = window.mySimulation.t(`grade_charter`);
            else if (fin <= -10) performance = window.mySimulation.t(`grade_efficiency`);
            else if (composite >= 55) performance = window.mySimulation.t(`grade_mixed`);

            const insights = [];
            if (adopted && trusted && compliant && profitable) insights.push(window.mySimulation.t(`insight_responsible`));
            else if (exposed) insights.push(window.mySimulation.t(`insight_surveillance`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (fin < 0) insights.push(window.mySimulation.t(`insight_fin_negative`));
            else if (fin >= 60) insights.push(window.mySimulation.t(`insight_fin_strong`));
            if (ds.surveillanceLed) insights.push(window.mySimulation.t(`insight_purpose`));
            if (ds.symbolicSafeguard) insights.push(window.mySimulation.t(`insight_symbolic`));
            if (ds.analyticsOff) insights.push(window.mySimulation.t(`insight_analyticsoff`));
            if (popia < 45) insights.push(window.mySimulation.t(`insight_popia`));
            if (trust >= 65 && adoption >= 65) insights.push(window.mySimulation.t(`insight_trusted`));

            return {
                adoption: adoption,
                trust: trust,
                popia: popia,
                fin: fin,
                adopted: adopted,
                trusted: trusted,
                compliant: compliant,
                profitable: profitable,
                exposed: exposed,
                met: (adopted && trusted && compliant && profitable && composite >= 75),
                symbolic: !!ds.symbolicSafeguard,
                finBlown: (fin <= -10),
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || ``;
            const met = !!s.met;
            const badge = met
                ? `<span class="sentinelsim-cm-badge sentinelsim-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="sentinelsim-cm-badge sentinelsim-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.exposed) failBadge += ` <span class="sentinelsim-cm-badge sentinelsim-cm-no">` + T(`cm_backlash`) + `</span>`;
            if (s.symbolic) failBadge += ` <span class="sentinelsim-cm-badge sentinelsim-cm-no">` + T(`cm_charter`) + `</span>`;
            if (s.finBlown) failBadge += ` <span class="sentinelsim-cm-badge sentinelsim-cm-no">` + T(`cm_efficiency`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="sentinelsim-cm-metric"><span class="sentinelsim-cm-mv">` + (Math.round(s.adoption || 0) + `%`) + `</span><span class="sentinelsim-cm-ml">` + T(`cm_m_adoption`) + `</span></div>`
                + `<div class="sentinelsim-cm-metric"><span class="sentinelsim-cm-mv">` + Math.round(s.trust || 0) + `</span><span class="sentinelsim-cm-ml">` + T(`cm_m_trust`) + `</span></div>`
                + `<div class="sentinelsim-cm-metric"><span class="sentinelsim-cm-mv">` + Math.round(s.popia || 0) + `</span><span class="sentinelsim-cm-ml">` + T(`cm_m_popia`) + `</span></div>`
                + `<div class="sentinelsim-cm-metric"><span class="sentinelsim-cm-mv">` + Math.round(s.fin || 0) + `</span><span class="sentinelsim-cm-ml">` + T(`cm_m_fin`) + `</span></div>`;
            return ``
                + `<div class="sentinelsim-completion">`
                +   `<div class="sentinelsim-cm-head">`
                +     `<div class="sentinelsim-cm-score">` + score + `<span class="sentinelsim-cm-score-max">/100</span></div>`
                +     `<div class="sentinelsim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="sentinelsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="sentinelsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="sentinelsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.surveillanceLed) return window.mySimulation.t(`hint_surveillance`);
            if (ds.symbolicSafeguard) return window.mySimulation.t(`hint_symbolic`);
            if (ds.fin <= -10 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_fin`);
            if (ds.adoption < 45 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_adoption`);
            if (state.currentPeriod >= 3 && ds.popia < 40) return window.mySimulation.t(`hint_popia`);
            if (ds.adoption >= 65 && ds.trust >= 60 && ds.popia >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

